import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"مخطط علم الآثار خارج الموقع بمرآة النسخ","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0085-复制镜异地考古方案.md","filePath":"ar/0085-复制镜异地考古方案.md"}'),o={name:"ar/0085-复制镜异地考古方案.md"};function l(h,t,i,n,p,s){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="مخطط-علم-الآثار-خارج-الموقع-بمرآة-النسخ" tabindex="-1">مخطط علم الآثار خارج الموقع بمرآة النسخ <a class="header-anchor" href="#مخطط-علم-الآثار-خارج-الموقع-بمرآة-النسخ" aria-label="Permalink to &quot;مخطط علم الآثار خارج الموقع بمرآة النسخ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>85</td></tr><tr><td>الوحدة</td><td>التفاعل عبر الأبعاد وقواعد الزمن</td></tr><tr><td>الكلمات المفتاحية</td><td>مرآة النسخ، علم الآثار خارج الموقع، المسح المكاني، إعادة بناء النسخة، صفر تلامس</td></tr></tbody></table><h2 id="أولاً-نظرة-عامة-على-المخطط" tabindex="-1">أولاً: نظرة عامة على المخطط <a class="header-anchor" href="#أولاً-نظرة-عامة-على-المخطط" aria-label="Permalink to &quot;أولاً: نظرة عامة على المخطط&quot;">​</a></h2><p>مخطط علم الآثار خارج الموقع بمرآة النسخ هو المخطط التقني القياسي لعلم الآثار عبر الأبعاد وعلم الآثار بالارتداد الزمني في كون هنغ يوان، وفكرته الجوهرية «لا ندخل، ولا نلمس، بل ننسخ فقط». يتطلب علم الآثار التقليدي دخول العاملين شخصياً إلى الموقع الأثري لإجراء الحفائر، مما يسبب حتماً تدخلاً فيزيائياً وتلوثاً بيئياً للموقع. أما مخطط مرآة النسخ، فينسخ الهدف الأثري نسخاً كاملاً في فضاء معزول خارج الموقع، عبر تقنية المبادئ القانونية المكانية ودون لمس الأصل إطلاقاً، ثم يجري جميع العمليات الأثرية داخل الفضاء المعزول.</p><p>«خارج الموقع» هي السمة المفتاحية لهذا المخطط. تكتمل عملية النسخ في منطقة آمنة مجاورة للبُعد المستهدف أو الفترة المستهدفة، لكن توليد النسخة وكل البحوث الأثرية اللاحقة تتم بالكامل في فضاء مستقل معزول تماماً عن الهدف. وهذا يعني أن العاملين في علم الآثار لا يحتاجون من البداية إلى النهاية إلى دخول المنطقة المستهدفة، ولا حتى البُعد المستهدف — إذ يمكن إتمام العملية الأثرية بأكملها عن بُعد في فضاء معزول داخل البُعد الخاص.</p><p>الأساس التقني لمخطط علم الآثار خارج الموقع بمرآة النسخ هو التطبيق الرفيع لنظام تسيير المبادئ القانونية المكانية. فقط المزارعون الذين بلغوا المستوى الرابع (مرحلة فاكونغ) أو أعلى من نظام تسيير المبادئ القانونية المكانية، أو الراكبون في مركبة مرآة نسخ بمستوى تقني مكافئ، يستطيعون تنفيذ عمليات نسخ فائقة الدقة. حالياً، حقق كون هنغ يوان الإنتاج الصناعي المتسلسل لمرايا النسخ؛ ويمكن لمزارعي المستوى الثالث (مرحلة هواكونغ) تشغيل معدات مرايا النسخ من النوع القياسي لإنجاز المهام الأثرية الروتينية.</p><h2 id="ثانياً-المبادئ-التقنية-لمرآة-النسخ" tabindex="-1">ثانياً: المبادئ التقنية لمرآة النسخ <a class="header-anchor" href="#ثانياً-المبادئ-التقنية-لمرآة-النسخ" aria-label="Permalink to &quot;ثانياً: المبادئ التقنية لمرآة النسخ&quot;">​</a></h2><p>المكونان الجوهريان لمرآة النسخ هما «مصفوفة مسح القوانين المكانية» و«معيد بناء حالات الجسيمات». تنقسم عملية عمله إلى ثلاث مراحل:</p><h3 id="_2-1-مرحلة-المسح-المكاني" tabindex="-1">2.1 مرحلة المسح المكاني <a class="header-anchor" href="#_2-1-مرحلة-المسح-المكاني" aria-label="Permalink to &quot;2.1 مرحلة المسح المكاني&quot;">​</a></h3><p>بعد نشر مرآة النسخ، يُجرى أولاً مسح شامل للقوانين المكانية للمنطقة المستهدفة. تبعث مصفوفة المسح موجات مكانية عالية التردد تخترق جميع البنى المادية والطاقية في المنطقة المستهدفة، وتسجل جميع المتغيرات الكمية لكل جسيم، بما فيها الموقع والزخم واللف والحالة الطاقية. وفي الوقت نفسه، تكتشف مصفوفة المسح توزيع حقول الطاقة، وتموجات متغيرات القوانين، وبقايا بصمات الوعي في المنطقة المستهدفة.</p><p>عملية المسح سلبية تماماً — فالموجات المكانية لا تغير أي حالة من حالات المادة التي تخترقها، وبالتالي لا تسبب أي تدخل في الموقع الأثري. تعتمد دقة المسح على المستوى التقني لمرآة النسخ؛ فدقة مسح معدات النوع القياسي على المستوى دون الذري، بينما يمكن لمعدات البحث الراقية بلوغ مستوى الكواركات.</p><h3 id="_2-2-مرحلة-نقل-البيانات" tabindex="-1">2.2 مرحلة نقل البيانات <a class="header-anchor" href="#_2-2-مرحلة-نقل-البيانات" aria-label="Permalink to &quot;2.2 مرحلة نقل البيانات&quot;">​</a></h3><p>تنقل البيانات الهائلة التي حصل عليها المسح إلى الفضاء المعزول عبر القناة المشفرة لشبكة المرساة. يعتمد نقل البيانات «بروتوكول تشفير الحالات الكمية»، لضمان عدم سرقة البيانات أو العبث بها أثناء النقل. حجم البيانات بالغ الضخامة — فمنطقة بحجم غرفة عادية، يبلغ حجم بيانات المسح الكاملة نحو 10 أس 30 بايتاً، ويتطلب إكمال النقل في وقت معقول الاستعانة بقناة البيانات عالية الأبعاد لشبكة المرساة.</p><h3 id="_2-3-مرحلة-إعادة-بناء-النسخة" tabindex="-1">2.3 مرحلة إعادة بناء النسخة <a class="header-anchor" href="#_2-3-مرحلة-إعادة-بناء-النسخة" aria-label="Permalink to &quot;2.3 مرحلة إعادة بناء النسخة&quot;">​</a></h3><p>بعد استلام البيانات، يعيد معيد بناء حالات الجسيمات في الفضاء المعزول بناء النسخة الكاملة للمنطقة المستهدفة جسيماً بعد جسيم في الفضاء المعزول، وفق المتغيرات الدقيقة المسجلة في المسح. تبدأ عملية إعادة البناء من جسيمات المستوى الأدنى، وتنشئ طبقة بعد طبقة: الذرات، والجزيئات، والبنى المادية، وحقول الطاقة، وبصمات الوعي. وبعد اكتمال إعادة البناء، تكون النسخة مطابقة تماماً للأصل على المستوى الفيزيائي — بما فيه مادة القطع الأثرية وبنيتها وعلامات أسطحها وأضرارها الداخلية، بل وحقول الطاقة وبصمات الوعي المتبقية.</p><p>يجب التنبيه بوجه خاص إلى أن «بصمات الوعي» في النسخة هي بقايا وعي بيئي امتصها الأصل خلال وجوده الطويل، وليست كيانات وعي حقيقية. لا تملك النسخة وعياً ذاتياً، ولا تولد أي نشاط وعي جديد. وقد تأكدت هذه النقطة بالتفسير القضائي لمحكمة التكافل: لا تدخل النسخة في نطاق «الحياة»، والبحث في النسخة لا يمس قضايا أخلاقيات الحياة.</p><h2 id="ثالثاً-تصنيف-مرآة-النسخ-وسيناريوهات-استخدامها" tabindex="-1">ثالثاً: تصنيف مرآة النسخ وسيناريوهات استخدامها <a class="header-anchor" href="#ثالثاً-تصنيف-مرآة-النسخ-وسيناريوهات-استخدامها" aria-label="Permalink to &quot;ثالثاً: تصنيف مرآة النسخ وسيناريوهات استخدامها&quot;">​</a></h2><p>وفقاً لنطاق النسخ ودقته ووظيفته، تقسم مرايا النسخ إلى الفئات الأربع التالية:</p><table tabindex="0"><thead><tr><th>الطراز</th><th>نطاق النسخ</th><th>مستوى الدقة</th><th>السيناريو المطبق</th><th>متطلب زراعة المشغل</th></tr></thead><tbody><tr><td>النوع القياسي (CM-S)</td><td>حتى 100 متر مكعب</td><td>دون ذري</td><td>علم الآثار الروتيني للقطع المفردة والبقايا الصغيرة</td><td>مرحلة هواكونغ (المستوى الثالث)</td></tr><tr><td>النوع الموسع (CM-E)</td><td>حتى 10000 متر مكعب</td><td>دون ذري</td><td>النسخ الكلي للمباني الكبيرة ومجموعات البقايا على مستوى القرية</td><td>مرحلة فاكونغ (المستوى الرابع)</td></tr><tr><td>النوع البحثي (CM-R)</td><td>حتى 1000 متر مكعب</td><td>مستوى الكواركات</td><td>بحث القطع الأثرية الثمينة التي تتطلب تحليلاً فائق الدقة</td><td>مرحلة فاكونغ (المستوى الرابع) + المستوى الثالث من نظام الاستنتاج التكراري</td></tr><tr><td>النوع الخاص (CM-X)</td><td>حتى كيلومتر مكعب واحد</td><td>دون ذري</td><td>النسخ الكلي الإنقاذي لمجموعات البقايا على مستوى المدينة</td><td>مرحلة يوانكونغ (المستوى الخامس) أو مساندة المركبة</td></tr></tbody></table><p>بالنسبة للبيئات الخاصة مثل أبعاد القوانين المفتتة، يلزم استخدام «مرآة نسخ متوافقة مع القوانين» معدلة بوجه خاص، تستطيع مصفوفة المسح فيها التكيف مع بيئات القوانين غير المستقرة، بما يضمن الحصول على بيانات مسح دقيقة حتى وسط تموجات القوانين.</p><h2 id="رابعاً-نقاط-التشغيل-الأساسية-لعلم-الآثار-خارج-الموقع" tabindex="-1">رابعاً: نقاط التشغيل الأساسية لعلم الآثار خارج الموقع <a class="header-anchor" href="#رابعاً-نقاط-التشغيل-الأساسية-لعلم-الآثار-خارج-الموقع" aria-label="Permalink to &quot;رابعاً: نقاط التشغيل الأساسية لعلم الآثار خارج الموقع&quot;">​</a></h2><p>يتطلب مخطط علم الآثار خارج الموقع بمرآة النسخ الانتباه إلى النقاط الأساسية التالية في التشغيل الفعلي:</p><ol><li><p><strong>اختيار موضع النشر</strong>: يجب نشر مرآة النسخ خارج مسافة أمان القوانين للمنطقة المستهدفة، بما يضمن تغطية نطاق المسح للهدف، ويتجنب في الوقت نفسه تسبب الجهاز نفسه في اضطراب قوانين المنطقة المستهدفة. عادة ما تزيد مسافة الأمان عن 3 أمثال البعد الأقصى للمنطقة المستهدفة.</p></li><li><p><strong>اختيار توقيت النسخ</strong>: بالنسبة لعلم الآثار بالارتداد الزمني، يجب إجراء نشر مرآة النسخ ومسحها في «فترة سكون القوانين» للفترة المستهدفة، وتجنب عمليات النسخ في لحظة وقوع الأحداث التاريخية الكبرى — إذ تكون كثافة السلاسل السببية في تلك اللحظات عالية للغاية، ويرتفع استهلاك الطاقة لعمليات النسخ ارتفاعاً كبيراً، وقد يحدث اضطراب خفيف في الخط السببي.</p></li><li><p><strong>التحقق من سلامة النسخة</strong>: بعد اكتمال إعادة بناء النسخة، يجب إجراء «التحقق من تطابق النسخة مع الأصل». طريقة التحقق هي مسح النسخة مرة ثانية ومقارنة بيانات المسح بالبيانات الأصلية جسيماً بجسيم؛ ويجب أن تقل نسبة الخطأ عن 10 أس سالب 12. وإذا تجاوزت نسبة الخطأ المعيار، يجب إتلاف النسخة وإعادة النسخ.</p></li><li><p><strong>استراتيجية النسخ متعدد الجولات</strong>: بالنسبة للبقايا فائقة الضخامة، قد لا يغطي النسخ الواحد كل المنطقة. عندئذ تعتمد استراتيجية «النسخ متعدد الجولات المقسم المناطق»، إذ تقسم البقايا إلى مناطق متعددة تنسخ كل على حدة، ثم تجمع في الفضاء المعزول. ويجب عند الجمع ضمان اتصال سلس بلا فجوات لحالات الجسيمات عند حدود المناطق المتجاورة، دون حدوث فالق في القوانين.</p></li></ol><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>مخطط علم الآثار خارج الموقع بمرآة النسخ نموذج لتطبيق كون هنغ يوان الهندسي لقوانين المبادئ القانونية المكانية. عبر المسار التقني «النسخ بلا تلامس، والبحث خارج الموقع»، يحل المخطط جذرياً التناقض بين «اكتساب المعرفة» و«حماية الموقع» في علم الآثار التقليدي. لا يرفع هذا المخطط كفاءة علم الآثار ارتفاعاً كبيراً فحسب، بل الأهم أنه يضمن ألا تترك أي عملية أثرية أي أثر على الحضارة المستهدفة أو الموقع التاريخي — محققاً حقاً «رحلت في صمت، كما أتيت في صمت».</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>84-考古协议总纲 (البروتوكول العام لعلم الآثار)</li><li>86-隔离空间低污染流程 (إجراء التلوث المنخفض للفضاءات المعزولة)</li><li>63-复制镜技术原理 (المبادئ التقنية لمرآة النسخ)</li></ul>',27)])])}const b=a(o,[["render",l]]);export{c as __pageData,b as default};
